from typing import List

class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)

        limit = k - 1
        choose_sum = [0] * n
        row = [0] * k
        row[0] = 1

        for m in range(n):
            choose_sum[m] = sum(row) % MOD
            if m + 1 < n:
                upto = min(limit, m + 1)
                for j in range(upto, 0, -1):
                    row[j] = (row[j] + row[j - 1]) % MOD

        ans = 0
        for i, x in enumerate(nums):
            ways_as_max = choose_sum[i]
            ways_as_min = choose_sum[n - 1 - i]
            ans = (ans + (x % MOD) * (ways_as_max + ways_as_min)) % MOD

        return ans
